script:
var doc = Document;
// Goal: add a new storey with its own floor plan and a structural grid line so later work has
// somewhere to draw. Reads at top level, writes in one block.

// 1. Find the highest existing level; the new one goes 12' above it.
Autodesk.Revit.DB.Level top = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  if (top == null || l.Elevation > top.Elevation) top = l;
}
double elevation = (top == null ? 0.0 : top.Elevation) + 12.0;

// 2. The view type for floor plans. ViewPlan.Create needs a ViewFamilyType whose ViewFamily is
//    FloorPlan (CeilingPlan and StructuralPlan are the other plan families).
Autodesk.Revit.DB.ViewFamilyType floorPlanType = null;
foreach (Autodesk.Revit.DB.ViewFamilyType vft in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.ViewFamilyType))) {
  if (vft.ViewFamily == Autodesk.Revit.DB.ViewFamily.FloorPlan) { floorPlanType = vft; break; }
}
if (floorPlanType == null) throw new System.Exception("no FloorPlan ViewFamilyType in this document");

return Connector.WithTransaction(doc, () => {
  // 3. Create the level. Level.Create takes the elevation in feet; the name is generated
  //    ("Level 3") and can be set through Name, which must be unique among levels.
  var level = Autodesk.Revit.DB.Level.Create(doc, elevation);
  level.Name = "Level " + System.Guid.NewGuid().ToString("N").Substring(0, 6);

  // 4. Create its floor plan. Unlike the Level tool in the UI (with "Make Plan View" on),
  //    Level.Create does NOT create a plan view. A later "find the plan for this level" lookup
  //    (step 5) then finds nothing, and passing that null view to NewRoomTag/NewDimension fails
  //    deep inside Revit with an ArgumentNullException. Annotation calls accept any non-template
  //    plan, not only one scoped to the element's level; a plan of this level is simply the one
  //    the drawings want.
  var plan = Autodesk.Revit.DB.ViewPlan.Create(doc, floorPlanType.Id, level.Id);
  plan.Name = level.Name + " plan";

  // 5. Look a plan up by its level later: ViewPlan.GenLevel is the level a plan is generated for
  //    (null for drafting-style plans), so filter on GenLevel.Id, skipping view templates.
  Autodesk.Revit.DB.ViewPlan found = null;
  foreach (Autodesk.Revit.DB.ViewPlan v in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.ViewPlan))) {
    if (!v.IsTemplate && v.GenLevel != null && v.GenLevel.Id == level.Id) { found = v; break; }
  }

  // 6. A grid line. Grid.Create takes a bound Line (or an Arc); grids are datum elements that span
  //    all levels, so no level argument. Name it as the drawings will label it.
  var grid = Autodesk.Revit.DB.Grid.Create(doc, Autodesk.Revit.DB.Line.CreateBound(
      new Autodesk.Revit.DB.XYZ(-10, -10, elevation), new Autodesk.Revit.DB.XYZ(-10, 50, elevation)));
  grid.Name = "G" + System.Guid.NewGuid().ToString("N").Substring(0, 4);
  doc.Regenerate();

  // 7. Verify: the plan found by GenLevel is the one created, and the grid is visible in it.
  int gridsInPlan = new Autodesk.Revit.DB.FilteredElementCollector(doc, plan.Id)
      .OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_Grids).WhereElementIsNotElementType().GetElementCount();
  return new {
    levelId = level.Id.Value, levelName = level.Name, elevationFeet = level.Elevation,
    planId = plan.Id.Value, planFoundByGenLevel = found != null && found.Id == plan.Id,
    gridId = grid.Id.Value, gridName = grid.Name, gridVisibleInPlan = gridsInPlan >= 1
  };
});
